WITH daily_brand AS ( SELECT cr.cr_returned_date_sk AS returned_date, i.i_brand AS brand, td.t_hour AS hour_of_day, SUM(cr.cr_net_loss) AS daily_brand_net_loss FROM catalog_returns cr JOIN item i ON cr.cr_item_sk = i.i_item_sk JOIN time_dim td ON cr.cr_returned_time_sk = td.t_time_sk JOIN customer cust ON cr.cr_refunded_customer_sk = cust.c_customer_sk WHERE cust.c_preferred_cust_flag = 'Y' GROUP BY cr.cr_returned_date_sk, i.i_brand, td.t_hour ) SELECT returned_date, brand, hour_of_day, daily_brand_net_loss, SUM(daily_brand_net_loss) OVER (PARTITION BY brand ORDER BY returned_date, hour_of_day ROWS UNBOUNDED PRECEDING) AS cumulative_brand_net_loss, NTILE(4) OVER (PARTITION BY returned_date ORDER BY daily_brand_net_loss DESC) AS loss_quartile FROM daily_brand WHERE daily_brand_net_loss > 0 ORDER BY returned_date, brand, hour_of_day
